Verilog()

@quartz struct Blink
  @in  rst::Bool = false  active=:low
  @out led::Bool
  n::Bits{24} = 0
end

@on Blink posedge(clk) begin
  @reset(rst)
  n ← n + 1
  led ← n[23]
end

write(stdout, Blink, Verilog());

module Blink (
  input wire clk_i,
  input wire rst_ni,
  output wire led_o
);

  wire clk = clk_i;
  wire rst = ~rst_ni;
  reg led;
  reg [23:0] n;

  wire [23:0] w5 = n + 24'h1;
  wire w6 = n[23];

  always @(posedge clk_i) begin
    if (rst) begin
      n &lt;= 24'h0;
    end else begin
      n &lt;= w5;
      led &lt;= w6;
    end
  end

  assign led_o = led;
endmodule


write("blink.v", Blink, Verilog()) writes a file. The module is a type: a parametric module is written per instantiation, write(io, Shift{16}, Verilog()).
The options:

name = :blink names the Verilog module something other than the Julia type.
suffix = false turns off the direction suffixes on the pins (n_i, led_o). A pin asserted low then keeps just _n, since it cannot share the name of the value behind it.
inits = :all initializes every register in the Verilog, for a simulator that would otherwise start them at x. The default initializes only static fields; see modules for why.
debug = true emits the block’s @info and @check as $display and $error.

Submodules and black boxes are written along with the module that instantiates them, one Verilog module each. Black boxes are instantiated, not defined: their definitions come from the vendor.






NoteOther outputs



Verilog is one Format among several — VCD and LPF are others — and a new one, for another HDL, a netlist or a report, is a write method of its own. Custom emitters shows how to write one.

An example
A UART transmitter: a byte in, a serial frame out with a parity bit. The frame is a sequence of steps, each one clock; the bit timing is a countdown register and the start strobe is an edge detector, each doing its own bookkeeping.

using QuartzHDL

const BIT_TIME = 9                   # clocks per bit, less one: 100 kbaud from 1 MHz

@quartz struct UartTx
  # interface wires
  @in  data::Bits{8}                 # 8-bit data to transmit
  @in  send::Bool                    # on rising edge of send
  @in  rst::Bool active=:low         # reset signal, asserted low
  @out tx::Bool = true               # TX pin of the UART
  @out busy::Bool active=:low        # busy signal, asserted low
  # internal state
  step::Step                         # state machine step
  send_e::Edge                       # edge detector for send input
  shift::Bits{8}                     # transmit shift register
  parity::Bool                       # parity bit
  baud_timer::Timeout{7}             # timer to control baud rate
end

@on UartTx posedge(clk) begin
  @reset(rst)                        # reset module when rst is asserted
  send_e ← send
  @sequence Frame step begin
    @when rose(send_e)               # wait for a send strobe, then
    shift ← data
    parity ← isodd(popcount(data))   # a Julia function, computed in hardware
    tx ← false                       # start bit
    baud_timer ← BIT_TIME
    @repeat 8 begin
      @when expired(baud_timer)      # one bit time later
      tx ← shift[0]                  # a data bit, LSB first
      shift ← shift &gt;&gt; 1
      baud_timer ← BIT_TIME
    end
    @then @when expired(baud_timer)
    tx ← parity                      # transmit parity bit
    baud_timer ← BIT_TIME
    @then @when expired(baud_timer)
    tx ← true                        # stop bit
    baud_timer ← BIT_TIME
    @then @when expired(baud_timer)  # hold it, then back to waiting for send
  end
  busy ← step != Frame.START
end

The @quartz struct declares the ports and the registers. @on says what happens on each rising edge of clk: ← is a register write that lands at the end of the cycle, exactly like Verilog’s &lt;=.
It is ordinary Julia, so it runs as such. A simulation clocks it at a real rate, records the pins you ask for, and hands back signals you can index by time, test, and plot:

using QuartzHDL.Units, Plots

sim = Simulation(UartTx(); clocks=(clk=1MHz,), watch="*")
out = @run sim begin
  sim.data = Bits{8}('A')
  advance_by(5µs)                   # a few clocks in, strobe send
  sim.send = true
  advance_by(5µs)
  sim.send = false
  advance_by(120µs)
end
plot(out, "clk", "send", "tx", "busy")




The same file compiles to Verilog from the command line — a case over the sequence’s steps, the state machine you would have written by hand:
$ quartz uart.jl --top UartTx -o uart.v
Or from Julia, writing the module type out:

write(stdout, UartTx, Verilog());

module UartTx (
  input wire clk_i,
  input wire send_i,
  input wire [7:0] data_i,
  input wire rst_ni,
  output wire tx_o,
  output wire busy_no
);

  localparam [3:0] Frame_START = 4'h0;
  localparam [3:0] Frame_step_1 = 4'h1;
  localparam [3:0] Frame_step_2 = 4'h2;
  localparam [3:0] Frame_step_3 = 4'h3;
  localparam [3:0] Frame_step_4 = 4'h4;
  localparam [3:0] Frame_step_5 = 4'h5;
  localparam [3:0] Frame_step_6 = 4'h6;
  localparam [3:0] Frame_step_7 = 4'h7;
  localparam [3:0] Frame_step_8 = 4'h8;
  localparam [3:0] Frame_step_9 = 4'h9;
  localparam [3:0] Frame_step_10 = 4'ha;
  localparam [3:0] Frame_step_11 = 4'hb;

  wire clk = clk_i;
  wire send = send_i;
  wire [7:0] data = data_i;
  wire rst = ~rst_ni;
  reg tx;
  reg busy;
  reg [3:0] step;
  reg send_e;
  reg send_e_prev;
  reg [7:0] shift;
  reg parity;
  reg [6:0] baud_timer;

  wire w11 = baud_timer == 7'h0;
  wire [6:0] w13 = baud_timer - 7'h1;
  wire [6:0] w14 = w11 ? baud_timer : w13;
  wire w16 = step == Frame_START;
  wire w19 = ~send_e_prev;
  wire w20 = send_e & w19;
  wire [3:0] w21 = data[0] + data[1] + data[2] + data[3] + data[4] + data[5] + data[6] + data[7];
  wire w22 = w21[0];
  wire w24 = step == Frame_step_1;
  wire w26 = baud_timer == 7'h0;
  wire w27 = shift[0];
  wire [7:0] w28 = shift &gt;&gt; 1;
  wire w30 = step == Frame_step_2;
  wire w32 = baud_timer == 7'h0;
  wire w33 = shift[0];
  wire [7:0] w34 = shift &gt;&gt; 1;
  wire w36 = step == Frame_step_3;
  wire w38 = baud_timer == 7'h0;
  wire w39 = shift[0];
  wire [7:0] w40 = shift &gt;&gt; 1;
  wire w42 = step == Frame_step_4;
  wire w44 = baud_timer == 7'h0;
  wire w45 = shift[0];
  wire [7:0] w46 = shift &gt;&gt; 1;
  wire w48 = step == Frame_step_5;
  wire w50 = baud_timer == 7'h0;
  wire w51 = shift[0];
  wire [7:0] w52 = shift &gt;&gt; 1;
  wire w54 = step == Frame_step_6;
  wire w56 = baud_timer == 7'h0;
  wire w57 = shift[0];
  wire [7:0] w58 = shift &gt;&gt; 1;
  wire w60 = step == Frame_step_7;
  wire w62 = baud_timer == 7'h0;
  wire w63 = shift[0];
  wire [7:0] w64 = shift &gt;&gt; 1;
  wire w66 = step == Frame_step_8;
  wire w68 = baud_timer == 7'h0;
  wire w69 = shift[0];
  wire [7:0] w70 = shift &gt;&gt; 1;
  wire w72 = step == Frame_step_9;
  wire w74 = baud_timer == 7'h0;
  wire w76 = step == Frame_step_10;
  wire w78 = baud_timer == 7'h0;
  wire w80 = step == Frame_step_11;
  wire w82 = baud_timer == 7'h0;
  wire w84 = step != Frame_START;

  always @(posedge clk_i) begin
    if (rst) begin
      tx &lt;= 1'h1;
    end else begin
      send_e_prev &lt;= send_e;
      baud_timer &lt;= w14;
      send_e &lt;= send;
      case (step)
        Frame_START: begin
          if (w20) begin
            step &lt;= Frame_step_1;
            shift &lt;= data;
            parity &lt;= w22;
            tx &lt;= 1'h0;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_1: begin
          if (w26) begin
            step &lt;= Frame_step_2;
            tx &lt;= w27;
            shift &lt;= w28;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_2: begin
          if (w32) begin
            step &lt;= Frame_step_3;
            tx &lt;= w33;
            shift &lt;= w34;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_3: begin
          if (w38) begin
            step &lt;= Frame_step_4;
            tx &lt;= w39;
            shift &lt;= w40;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_4: begin
          if (w44) begin
            step &lt;= Frame_step_5;
            tx &lt;= w45;
            shift &lt;= w46;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_5: begin
          if (w50) begin
            step &lt;= Frame_step_6;
            tx &lt;= w51;
            shift &lt;= w52;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_6: begin
          if (w56) begin
            step &lt;= Frame_step_7;
            tx &lt;= w57;
            shift &lt;= w58;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_7: begin
          if (w62) begin
            step &lt;= Frame_step_8;
            tx &lt;= w63;
            shift &lt;= w64;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_8: begin
          if (w68) begin
            step &lt;= Frame_step_9;
            tx &lt;= w69;
            shift &lt;= w70;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_9: begin
          if (w74) begin
            step &lt;= Frame_step_10;
            tx &lt;= parity;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_10: begin
          if (w78) begin
            step &lt;= Frame_step_11;
            tx &lt;= 1'h1;
            baud_timer &lt;= 7'h9;
          end
        end
        Frame_step_11: begin
          if (w82) begin
            step &lt;= Frame_START;
          end
        end
        default: begin
          step &lt;= Frame_START;
        end
      endcase
      busy &lt;= w84;
    end
  end

  assign tx_o = tx;
  assign busy_no = ~busy;
endmodule


